//! Port of `packages/tui/src/utils.ts` @ pi 0.82.1 (2efa728).
//!
//! Terminal text utilities: visible width (Unicode EAW + ANSI aware), wrapping
//! with ANSI/OSC-8 preservation, truncation, column slicing and overlay segment
//! extraction. All width arithmetic is in terminal columns (`usize`).
//!
//! Intentional differences:
//! - Unicode primitives. Upstream regexes (`\p{Default_Ignorable_Code_Point}`,
//!   `\p{Control}`, `\p{Format}`, `\p{Mark}`, `\p{RGI_Emoji}`, `Script_Extensions`)
//!   run on the runtime's ICU (Node 24 / ICU 76). ICU 76 deviates from the raw
//!   Unicode 16.0.0 UCD files (broader script ranges covering unassigned gaps,
//!   a few post-16.0 marks/emoji), so the generated tables at the bottom of
//!   this file are produced from probes of the actual runtime behavior (the
//!   emoji sequence data is verified byte-identical to the Unicode 16.0
//!   emoji-sequences.txt / emoji-zwj-sequences.txt contents). Generation
//!   scripts are checked in under `scripts/` (`gen-tui-unicode-data.py` +
//!   `icu-probe*.mjs`; see the `@generated` marker at the bottom of this
//!   file). `eastAsianWidth()`
//!   comes from the vendored npm package `get-east-asian-width` v1.6.0 (Unicode
//!   17 data); it is implemented on `unicode-width` 0.2.x (also Unicode 17
//!   data) plus a correction set verified empirically over the whole code
//!   space against the pinned npm package (see `east_asian_width`).
//! - `Intl.Segmenter` (grapheme + word granularity) is replaced by
//!   `unicode-segmentation` 1.13.x (UAX #29, Unicode 17.0 data), which was
//!   verified to match ICU 76's extended grapheme clusters on the full
//!   cross-check corpus (including Thai/Lao AM clusters, ZWJ emoji, RI pairs,
//!   lone combining marks and post-16.0 marks); word segmentation
//!   (`get_word_segmenter`) is only used by T12 editor/word-navigation ports.
//! - `normalizeTerminalOutput` / the ANSI strip in `visible_width` copy whole
//!   characters instead of UTF-16 code units; the two are equivalent because
//!   surrogate halves of an astral character always stay adjacent (ANSI/ESC
//!   bytes are ASCII and can never sit between the halves).
//! - The width cache is a `Mutex<HashMap>` + insertion-order queue; the eviction
//!   policy (which entry is dropped at capacity) is unobservable, so upstream's
//!   `Map` first-key eviction is preserved in spirit.
//! - `extract_segments` uses a fresh `AnsiCodeTracker` per call instead of the
//!   upstream module-level pooled instance; semantics are identical (it is
//!   cleared at the start of every call).
//! - `is_whitespace_char` implements the ECMA-262 `\s` set exactly (includes
//!   U+FEFF, excludes U+0085, which differ from Rust's `char::is_whitespace`).

use std::collections::{HashMap, VecDeque};
use std::sync::{Mutex, MutexGuard};

use unicode_segmentation::UnicodeSegmentation;
use unicode_width::UnicodeWidthChar;

/// Shared grapheme segmenter — equivalent of the upstream module-level
/// `Intl.Segmenter(undefined, { granularity: "grapheme" })` instance.
pub struct GraphemeSegmenter;

/// `getGraphemeSegmenter` (utils.ts:10-12).
pub fn get_grapheme_segmenter() -> GraphemeSegmenter {
    GraphemeSegmenter
}

impl GraphemeSegmenter {
    /// Segment into extended grapheme clusters (UAX #29), like
    /// `Intl.Segmenter#segment(text, { granularity: "grapheme" })`.
    pub fn segment<'a>(&self, text: &'a str) -> unicode_segmentation::Graphemes<'a> {
        text.graphemes(true)
    }
}

/// Shared word segmenter — equivalent of the upstream module-level
/// `Intl.Segmenter(undefined, { granularity: "word" })` instance.
/// Only used by T12 editor / word-navigation ports so far.
pub struct WordSegmenter;

/// `getWordSegmenter` (utils.ts:17-19).
pub fn get_word_segmenter() -> WordSegmenter {
    WordSegmenter
}

impl WordSegmenter {
    /// Segment on UAX #29 word boundaries, yielding every substring including
    /// the whitespace/punctuation between words (like `Intl.Segmenter` word
    /// granularity, which also yields non-word segments).
    pub fn segment<'a>(&self, text: &'a str) -> unicode_segmentation::UWordBounds<'a> {
        text.split_word_bounds()
    }
}

/// Check if a grapheme cluster (after segmentation) could possibly be an RGI
/// emoji. This is a fast heuristic to avoid the expensive RGI emoji check.
/// The tested Unicode blocks are deliberately broad to account for future
/// Unicode additions. (utils.ts:27-37; keep the ranges byte-exact — narrowing
/// them would change widths of e.g. U+25FD/U+25FE, which upstream deliberately
/// does not treat as emoji.)
fn could_be_emoji(segment: &str) -> bool {
    let cp = segment.chars().next().map_or(0, |c| c as u32);
    (0x1f000..=0x1fbff).contains(&cp) // Emoji and Pictograph
        || (0x2300..=0x23ff).contains(&cp) // Misc technical
        || (0x2600..=0x27bf).contains(&cp) // Misc symbols, dingbats
        || (0x2b50..=0x2b55).contains(&cp) // Specific stars/circles
        || segment.contains('\u{fe0f}') // Contains VS16 (emoji presentation selector)
        || segment.encode_utf16().count() > 2 // Multi-codepoint sequences (ZWJ, skin tones, etc.)
}

/// `\p{RGI_Emoji}` matching for a whole grapheme cluster (utils.ts:42
/// `rgiEmojiRegex`). Sequences are matched against the generated Unicode 16.0
/// tables: single codepoints with Emoji_Presentation=Yes, Basic_Emoji
/// (base+VS16), keycaps, modifier sequences, flag RI-pairs, tag sequences and
/// ZWJ sequences.
fn is_rgi_emoji(segment: &str) -> bool {
    let cps: Vec<u32> = segment.chars().map(|c| c as u32).collect();
    match cps.as_slice() {
        [cp] => in_ranges(*cp, EMOJI_PRESENTATION_RANGES),
        [base, 0xfe0f] => in_ranges(*base, EMOJI_BASIC_BASES),
        [base, 0x1f3fb..=0x1f3ff] => in_ranges(*base, EMOJI_MODIFIER_BASES),
        [a, b] => RGI_FLAG_PAIRS
            .binary_search_by(|&(x, y)| (x, y).cmp(&(*a, *b)))
            .is_ok(),
        [base, 0xfe0f, 0x20e3] => in_ranges(*base, KEYCAP_BASES),
        _ => {
            contains_sequence(RGI_TAG_SEQUENCES, &cps) || contains_sequence(RGI_ZWJ_SEQUENCES, &cps)
        }
    }
}


