/// `parseOsc8Hyperlink` (utils.ts:359-377).
fn parse_osc8_hyperlink(ansi_code: &str) -> HyperlinkParse {
    if !ansi_code.starts_with("\x1b]8;") {
        return HyperlinkParse::NotHyperlink;
    }

    let terminator = if ansi_code.ends_with('\x07') {
        Osc8Terminator::Bel
    } else {
        Osc8Terminator::St
    };
    let term_len = match terminator {
        Osc8Terminator::Bel => 1,
        Osc8Terminator::St => 2,
    };
    if ansi_code.len() < 4 + term_len {
        return HyperlinkParse::NotHyperlink;
    }
    let body = &ansi_code[4..ansi_code.len() - term_len];
    let Some(separator_index) = body.find(';') else {
        return HyperlinkParse::NotHyperlink;
    };

    let params = &body[..separator_index];
    let url = &body[separator_index + 1..];
    if url.is_empty() {
        return HyperlinkParse::Close;
    }
    HyperlinkParse::Open(ActiveHyperlink {
        params: params.to_string(),
        url: url.to_string(),
        terminator,
    })
}

