/// undefined` — `undefined` (not an OSC 8 code) vs `null` (OSC 8 close with an
/// empty URL).
enum HyperlinkParse {
    NotHyperlink,
    Close,
    Open(ActiveHyperlink),
}

/// `parseOsc8Hyperlink` (utils.ts:359-377).
fn parse_osc8_hyperlink(ansi_code: &str) -> HyperlinkParse {
    if !ansi_code.starts_with("\x1b]8;") {
        return HyperlinkParse::NotHyperlink;
    }

    let terminator = if ansi_code.ends_with('\x07') {
        Osc8Terminator::Bel
    } else {
        Osc8Terminator::St
    };
    let term_len = match terminator {
        Osc8Terminator::Bel => 1,
        Osc8Terminator::St => 2,
    };
    if ansi_code.len() < 4 + term_len {
        return HyperlinkParse::NotHyperlink;
    }
    let body = &ansi_code[4..ansi_code.len() - term_len];
    let Some(separator_index) = body.find(';') else {
        return HyperlinkParse::NotHyperlink;
    };

    let params = &body[..separator_index];
    let url = &body[separator_index + 1..];
    if url.is_empty() {
        return HyperlinkParse::Close;
    }
    HyperlinkParse::Open(ActiveHyperlink {
        params: params.to_string(),
        url: url.to_string(),
        terminator,
    })
}

/// `formatOsc8Hyperlink` (utils.ts:379-381).
fn format_osc8_hyperlink(hyperlink: &ActiveHyperlink) -> String {
    match hyperlink.terminator {
        Osc8Terminator::Bel => format!("\x1b]8;{};{}\x07", hyperlink.params, hyperlink.url),
        Osc8Terminator::St => format!("\x1b]8;{};{}\x1b\\", hyperlink.params, hyperlink.url),
    }
}

/// `formatOsc8Close` (utils.ts:383-385).
fn format_osc8_close(terminator: Osc8Terminator) -> String {
    match terminator {
        Osc8Terminator::Bel => "\x1b]8;;\x07".to_string(),
        Osc8Terminator::St => "\x1b]8;;\x1b\\".to_string(),
    }
}

/// Scan for the first `\x1b[` followed by a run of digits/semicolons terminated
/// by `m`, mirroring the unanchored upstream regex `/\x1b\[([\d;]*)m/`; returns
/// the parameter string between `\x1b[` and `m`.
fn extract_sgr_params(ansi_code: &str) -> Option<&str> {
    let bytes = ansi_code.as_bytes();
    let mut pos = 0;
    while pos + 1 < bytes.len() {
        if bytes[pos] == 0x1b && bytes[pos + 1] == b'[' {
            let mut j = pos + 2;
            while j < bytes.len() && (bytes[j].is_ascii_digit() || bytes[j] == b';') {
                j += 1;
            }
            if j < bytes.len() && bytes[j] == b'm' {
                return Some(&ansi_code[pos + 2..j]);
            }
            // the run is digits/semicolons only, so no ESC can hide inside
            pos = j;
        } else {
            pos += 1;
        }
    }
    None
}

