/// Extract "before" and "after" segments from a line in a single pass
/// (utils.ts:1138-1209, `extractSegments`).
/// Used for overlay compositing where we need content before and after the
/// overlay region. Preserves styling from before the overlay that should
/// affect content after it.
pub fn extract_segments(
    line: &str,
    before_end: usize,
    after_start: usize,
    after_len: usize,
    strict_after: bool,
) -> Segments {
    let mut before = String::new();
    let mut before_width = 0usize;
    let mut after = String::new();
    let mut after_width = 0usize;
    let mut current_col = 0usize;
    let mut i = 0;
    let mut pending_ansi_before = String::new();
    let mut after_started = false;
    let after_end = after_start + after_len;

    // Track styling state so "after" inherits styling from before the overlay.
    // (Upstream pools a module-level tracker; a fresh one is equivalent.)
    let mut style_tracker = AnsiCodeTracker::default();

    while i < line.len() {
        if let Some(ansi) = extract_ansi_code(line, i) {
            // Track all SGR codes to know styling state at afterStart
            style_tracker.process(ansi.code);
            // Include ANSI codes in their respective segments
            if current_col < before_end {
                pending_ansi_before.push_str(ansi.code);
            } else if current_col >= after_start && current_col < after_end && after_started {
                // Only include after we've started "after" (styling already prepended)
                after.push_str(ansi.code);
            }
            i += ansi.length;
            continue;
        }

        let mut text_end = i;
        while text_end < line.len() && extract_ansi_code(line, text_end).is_none() {
            text_end += 1;
        }

        for segment in line[i..text_end].graphemes(true) {
            let w = grapheme_width(segment);

            if current_col < before_end && current_col + w <= before_end {
                if !pending_ansi_before.is_empty() {
                    before.push_str(&pending_ansi_before);
                    pending_ansi_before.clear();
                }
                before.push_str(segment);
                before_width += w;
            } else if current_col >= after_start && current_col < after_end {
                let fits = !strict_after || current_col + w <= after_end;
                if fits {
                    // On first "after" grapheme, prepend inherited styling from before overlay
                    if !after_started {
                        after.push_str(&style_tracker.get_active_codes());
                        after_started = true;
                    }
                    after.push_str(segment);
                    after_width += w;
                }
            }

            current_col += w;
            // Early exit: done with "before" only, or done with both segments
            let done_at = if after_len == 0 {
                before_end
            } else {
                after_end
            };
            if current_col >= done_at {
                break;
            }
        }
        i = text_end;
        let done_at = if after_len == 0 {
            before_end
        } else {
            after_end
        };
        if current_col >= done_at {
            break;
        }
    }

    Segments {
        before,
        before_width,
        after,
        after_width,
    }
}

