cat > /tmp/widthcheck/src/main.rs <<'EOF'
use pir_tui::utils::visible_width;
use serde_json::Value;
use std::io::Read;

fn main() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut mismatches = 0u64;
    let mut total = 0u64;
    for line in buf.lines() {
        if line.is_empty() { continue; }
        total += 1;
        let (js, w) = line.split_once('\t').unwrap();
        let s: String = serde_json::from_str::<Value>(js).unwrap().as_str().unwrap().to_string();
        let expected: usize = w.parse().unwrap();
        let got = visible_width(&s);
        if got != expected {
            mismatches += 1;
            if mismatches <= 60 {
                let mut esc = String::new();
                for c in s.chars() {
                    let cp = c as u32;
                    if cp < 0x20 || cp > 0x7e { esc.push_str(&format!("\\u{{{:X}}}", cp)); }
                    else { esc.push(c); }
                }
                println!("MISMATCH line={} expected={} rust={} s={}", total, expected, got, esc);
            }
        }
    }
    eprintln!("total={} mismatches={}", total, mismatches);
}
EOF
