    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut mismatches = 0u64;
    let mut total = 0u64;
    for line in buf.lines() {
        if line.is_empty() { continue; }
        total += 1;
        let (js, expected_json) = line.split_once('\t').unwrap();
        let v: Value = serde_json::from_str(js).unwrap();
        let args = v.as_array().unwrap();
        let s: String = args[1].as_str().unwrap().to_string();
        let got: Value = match args[0].as_str().unwrap() {
            "truncate" => json!(truncate_to_width(&s, args[2].as_u64().unwrap() as usize, args[3].as_str().unwrap(), args[4].as_bool().unwrap())),
            "wrap" => json!(wrap_text_with_ansi(&s, args[2].as_u64().unwrap() as usize)),
            "slice" => {
                let a = slice_by_column(&s, args[2].as_u64().unwrap() as usize, args[3].as_u64().unwrap() as usize, args[4].as_bool().unwrap());
                let b = slice_with_width(&s, args[2].as_u64().unwrap() as usize, args[3].as_u64().unwrap() as usize, args[4].as_bool().unwrap());
                json!([a, vec![b.0, b.1]])
            }
            "extract" => {
                let r = extract_segments(&s, args[2].as_u64().unwrap() as usize, args[3].as_u64().unwrap() as usize, args[4].as_u64().unwrap() as usize, args[5].as_bool().unwrap());
                json!({"before": r.before, "beforeWidth": r.before_width, "after": r.after, "afterWidth": r.after_width})
            }
            "normalize" => json!(normalize_terminal_output(&s)),
            _ => unreachable!(),
        };
        let expected: Value = serde_json::from_str(expected_json).unwrap();
        if got != expected {
            mismatches += 1;
            if mismatches <= 40 {
                println!("MISMATCH #{} line={}", mismatches, total);
                println!("  args: {}", js);
                println!("  expected: {}", expected_json);
                println!("  rust:     {}", got);
            }
        }
    }
    eprintln!("total={} mismatches={}", total, mismatches);
}
